      `RATE_SET sheet=${sheet} by=uma grade=B rate=12.50`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ben grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=20.00 due-total=4.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.00 due-total=6.00`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=2.00 claims=1`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=30.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=20.00 due-total=6.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.00 due-total=8.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=20.00 date=2026-03-10 number=2 due=6.00`,
      `CLAIM_VOIDED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=0.00 due-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=20.00 due-total=6.00`,
      `STATEMENT sheet=${sheet} by=vic name=Ada due-total=0.00 claims=0`,
      `PERSON_ADDED sheet=${sheet} by=vic name=Cam grade=C`,
      `ROLLUP sheet=${sheet} by=vic person=Cam claimed=0.00 due-total=n/a`
    ]);
  });
  test("rollup audit scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
