package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.time.LocalDate;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet never loaded before starts empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Clock clock;

    public SheetService(SheetRepository sheets, Clock clock) {
        this.sheets = sheets;
        this.clock = clock;
    }

    /** The sheet with this id, created empty when it was never loaded before. */
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, LocalDate.now(clock)));
            } catch (DataIntegrityViolationException e) {
                return sheets.findById(id).orElseThrow(() -> e); // created concurrently
            }
        });
    }

    /** The sheet's today: the date every date-dependent decision and default on the sheet uses. */
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Take the sheet's next claim number, holding the sheet locked until the transaction ends so
     *  claims opened at the same moment get different numbers. */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        long number = sheet.nextClaimNumber();
        sheets.saveAndFlush(sheet);
        return number;
    }

    /** Hold the sheet locked until the transaction ends, so changes to it made at the same moment
     *  wait their turn. */
    @Transactional
    public void lock(String id) {
        load(id);
        sheets.findLockedById(id).orElseThrow();
    }

    /** Change the sheet's today. */
    @Transactional
    public Sheet setToday(String id, LocalDate today) {
        Sheet sheet = load(id);
        sheet.setToday(today);
        return sheets.save(sheet);
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a person to the sheet. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId);
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, null);
        Person added = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        record("PERSON_ADDED", sheetId, user, added);
        return added;
    }

    /** Change a person's name and grade, from an editor that loaded the given version of them. */
    @Transactional
    public Person update(String sheetId, String user, Long id, long version, String name, String grade) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        if (person.getVersion() != version) {
            throw new StalePersonException(person);
        }
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, id);
        person.setName(trimmed);
        person.setGrade(grade);
        Person saved = people.saveAndFlush(person);
        record("PERSON_EDITED", sheetId, user, saved);
        return saved;
    }

    private void record(String event, String sheetId, String user, Person person) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + person.getGrade());
    }

    private void requireFreeName(String sheetId, String name, Long exceptId) {
        if (people.nameInUse(sheetId, name, exceptId)) {
            throw new NameInUseException(name);
        }
    }
}
