import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** The header that tells the server who is signed in, so it can record who made each change. */
export const USER_HEADER = 'X-User';

// Sends the signed-in user's name with every API request. The name is URI-encoded, since a header
// carries only plain ASCII; the server decodes it.
export const userHeader: HttpInterceptorFn = (req, next) => {
  const user = inject(Session).user();
  return next(user ? req.clone({ setHeaders: { [USER_HEADER]: encodeURIComponent(user) } }) : req);
};
  /** The sheet's rates by grade, each grade's from the earliest. */
  readonly rates = signal<Rate[]>([]);
  /** Each grade's rates by grade; a grade with no rate is absent. */
  readonly byGrade = computed(() => {
    const map = new Map<string, Rate[]>();
    for (const r of this.rates()) map.set(r.grade, [...(map.get(r.grade) ?? []), r]);
    return map;
  });
  /** Each grade's rate in force on the sheet's today; a grade with none is absent. */
  readonly current = computed(() => {
    const today = this.session.today();
    const map = new Map<string, string>();
    if (!today) return map;
    for (const [grade, rates] of this.byGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== null) map.set(grade, rate);
    }
    return map;
  });

  /** A grade's rates; none when the grade has no rate. */
  of(grade: string): Rate[] {
    return this.byGrade().get(grade) ?? [];
  }

  constructor() {

    public StatementController(StatementService service) {
        this.service = service;
    }

    /** Take a statement for the person. */
    @PostMapping
    public StatementTaken take(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        List<ClaimView> claims = service.take(sheet, SignedInUser.decode(user), personId).stream()
                .map(ClaimView::of).toList();
        return new StatementTaken(service.summary(sheet, personId), claims);
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }
}

